import{z as s,x as n,o as r,c as B,q as A,j as c,D as e,d as t,s as d,S as p,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"PEG 与 packrat","description":"","frontmatter":{"title":"PEG 与 packrat","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/peg-packrat.md","filePath":"cs/peg-packrat.md","lastUpdated":1791413859000}'),l={name:"cs/peg-packrat.md"};function i(P,a,G,C,D,m){const o=n("Mermaid");return r(),B("div",null,[a[2]||(a[2]=A('<h1 id="peg-与-packrat" tabindex="-1">PEG 与 packrat <a class="header-anchor" href="#peg-与-packrat" aria-label="Permalink to &quot;PEG 与 packrat&quot;">​</a></h1><div class="epigraph"><p>有序选择不是并：先试左边，成功则右边永不发生。记忆化后线性时间，但 Peg 的语言类与 CFG 交叉而不包含。</p><footer>—— 据 Ford, Parsing Expression Grammars, 2004；Ford, Packrat Parsing, 2002 整理</footer></div><p>上一课<a href="/cs/glr-parser">GLR</a>在 CFG 上保留全部推导。缺口是另一套前端习惯：<strong>PEG</strong>——<code>e1 / e2</code> 有序，且带 <code>&amp;</code>/<code>!</code> 谓词。packrat：每个位置、每个非终结符只算一次，线性于输入×规则。本课钉与 CFG 的差，不把 PEG 写成「更现代的 yacc」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CFG 的 <code>|</code> 是并，二义来自多条同时成功。PEG 的 <code>/</code>：左枝吃掉则右枝不看。左递归在朴素 PEG 里会无限递归，需改写或特殊处理。缺口是<strong>有序选择与谓词</strong>，不是再填 LALR 表。</p><p>packrat 用表记住 <code>(i, A)</code> 的成败与消耗长度，避免递归下降的指数。空间 \\(O(n\\cdot |G|)\\)，这是换时间的代价。</p><h3 id="不是" tabindex="-1"><code>/</code> 不是 <code>|</code> <a class="header-anchor" href="#不是" aria-label="Permalink to &quot;`/` 不是 `|`&quot;">​</a></h3><p><code>A / A B</code> 永远认短的 <code>A</code>，后面的 <code>B</code> 不是「另一条合法产生式」。把 yacc 文法机械换成 PEG 会静默改变语言。最长匹配要显式写成优先长枝，或用谓词。</p><p><span class="marginnote">数字实例：想让规则认「A 或 A B」，CFG 里写 <code>A | A B</code> 两种都试得通；PEG 里必须把长的写前面：<code>A B / A</code>。如果写成 <code>A / A B</code>，输入 &quot;AB&quot; 时左枝吃掉 &quot;A&quot; 就宣布成功，&quot;B&quot; 变成没人管的残留——解析不报错，但语言已经悄悄变了。</span></p><p><span class="marginnote">Ford 2004 POPL（PEG）；2002 ICFP（packrat）。PEGs 不能直接搬 CYK 的「成员 = 某非终结符推出」。本课不引用不存在的 arXiv 编号。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>手写或生成递归下降，每个解析函数对位置做记忆化。谓词 <code>&amp;e</code> 成功不消耗；<code>!e</code> 失败则成功。词法可并进同一 PEG，空白用显式规则吃掉——与 lex/yacc 分阶段对照，不是必须合一。</p>',12)),(r(),c(p,null,{default:e(()=>[d(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PEG%5B%22%E6%9C%89%E5%BA%8F%E8%A7%84%E5%88%99%22%5D%20--%3E%20RD%5B%22%E9%80%92%E5%BD%92%E4%B8%8B%E9%99%8D%22%5D%0A%20%20RD%20--%3E%20MEM%5B%22packrat%20%E8%A1%A8%22%5D%0A%20%20MEM%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%E6%89%AB%E6%8F%8F%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"工具链（如许多 PEG 生成器）默认无左递归；需要左结合表达式时用 Pratt 或循环，下一课。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"PEG 认的语言类与 CFG 不可比：有的 PEG 不是 CFG，有的 CFG 没有等价 PEG。间接左递归同样危险。错误信息：有序选择会把失败吞进左枝，诊断比 LR 的「此处期望 FOLLOW」更绕，后课错误恢复再对照。",-1)),(r(),c(p,null,{default:e(()=>[d(o,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20NO%5B%22%E6%97%A0%E8%AE%B0%E5%BF%86%E5%8C%96%EF%BC%9A%E6%9C%B4%E7%B4%A0%E9%80%92%E5%BD%92%E4%B8%8B%E9%99%8D%22%5D%0A%20%20%20%20P1%5B%22%E8%A7%84%E5%88%99%20A%20%E5%9C%A8%E4%BD%8D%E7%BD%AE%203%20%E5%A4%B1%E8%B4%A5%22%5D%20--%3E%20P2%5B%22%E6%8D%A2%E6%9D%A1%E8%B7%AF%E5%BE%84%E5%8F%88%E8%B5%B0%E5%88%B0%20A%403%22%5D%0A%20%20%20%20P2%20--%3E%20P3%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E8%BE%93%E5%85%A5%E9%87%8D%E6%89%AB%E4%B8%80%E9%81%8D%22%5D%0A%20%20%20%20P3%20--%3E%20P4%5B%22%E6%9C%80%E5%9D%8F%E6%8C%87%E6%95%B0%EF%BC%9A2%5En%20%E6%AC%A1%E9%87%8D%E7%AE%97%22%5D%0A%20%20end%0A%20%20subgraph%20YES%5B%22packrat%EF%BC%9A%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20%20%20M1%5B%22A%403%20%E5%A4%B1%E8%B4%A5%EF%BC%8C%E8%AE%B0%E8%BF%9B%E8%A1%A8%22%5D%20--%3E%20M2%5B%22%E5%86%8D%E9%81%87%E5%88%B0%20A%403%20%E7%9B%B4%E6%8E%A5%E6%9F%A5%E8%A1%A8%22%5D%0A%20%20%20%20M2%20--%3E%20M3%5B%22%E6%AF%8F%E4%B8%AA%20(%E4%BD%8D%E7%BD%AE%2C%20%E8%A7%84%E5%88%99)%20%E5%8F%AA%E7%AE%97%E4%B8%80%E6%AC%A1%22%5D%0A%20%20%20%20M3%20--%3E%20M4%5B%22%E7%BA%BF%E6%80%A7%EF%BC%9An%20%C3%97%20%E8%A7%84%E5%88%99%E6%95%B0%E6%AC%A1%22%5D%0A%20%20end%0A%20%20NO%20--%3E%7C%22%E5%8A%A0%E4%B8%80%E5%BC%A0%E8%A1%A8%22%7C%20YES%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p>这张图回答的问题是：packrat 靠什么把指数压成线性？朴素递归下降里，同一条规则在同一次失败后还会被不同路径反复重试，重试次数指数膨胀；packrat 给每个「位置 × 规则」的组合开一行表，算过一次成败与消耗长度就永久复用。组合数只有 \\(n \\times |G|\\)，总时间随之变线性——代价是这张表要占 \\(O(n\\cdot|G|)\\) 空间。</p><p><span class="marginnote">直觉类比：packrat 表就像做题时打的草稿——同一个「辅助线 + 已知条件」组合推过一次，就把结论抄在边上；之后不论哪条解题路径再走到这一步，看一眼草稿直接用，不再从头推。表就是那张按「位置 × 规则」编号的草稿纸。</span></p><p>不要用 PEG 证明 CFL 性质：泵引理对 PEG 不直接适用。本进阶课要的是实现策略，不是再开自动机层级。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GLL，不把 tree-sitter 的 GLR 方言说成 PEG。后课默认：PEG = 有序选择 + 可选 packrat；表达式优先级常另用 Pratt。下一课算符优先的手写分析。</p><p>无限前瞻谓词可使某些输入极慢，若未记忆化；packrat 压掉重复，压不掉「谓词每次扫很长」的常数。</p><p><span class="marginnote">常见误区：以为「packrat 是线性时间，所以 PEG 解析器总是最快的」。线性只封顶不保证快——表本身要花内存与查表时间，对很小的输入，一张 packrat 表的开销可能超过它省下的重算；另外左递归文法在 PEG 里干脆跑不终止。选解析方案仍要看文法形状，不是名字带「线性」就赢。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PEG 的 <code>/</code> 有序，语言不等于 CFG 并。</li><li>packrat 记忆化后线性，换空间。</li><li>不要把 yacc 文法直接当 PEG。</li><li>出处：Ford, 2002、2004。</li></ul>',9))])}const u=s(l,[["render",i]]);export{F as __pageData,u as default};
